// Results summaries on disk: `.memon/index/results/<experiment-id>.json`.
//
// A summary is reused only when its digest matches its content, it was
// generated by this release, its recorded input set equals the current one
// (the description file plus every declared member's README and result
// file, absent files recorded as absent) and every fingerprint is unchanged;
// otherwise it is regenerated and replaced atomically, best effort. Readers
// outside central re-take every fingerprint on every request; central may
// supply fingerprints from validated derived-index entries.

import { join } from 'node:path'
import {
  type PersistedFingerprint,
  sameFingerprint,
  takeFingerprint,
} from '../derived-index/fingerprint.js'
import { defaultIndexFs, errnoCode, type IndexFs } from '../derived-index/fs.js'
import { ensureIndexDirectory } from '../derived-index/gitignore.js'
import { randomHex8, resolveIndexPaths } from '../derived-index/paths.js'
import { listExperimentIds } from '../experiments/discover.js'
import { parseExperimentReadme } from '../experiments/parse.js'
import { splitFrontmatter } from '../frontmatter.js'
import { isRunPath } from '../ids.js'
import { parseReadme } from '../readme/parse.js'
import { formatIsoLocal } from '../time.js'
import { EXPERIMENT_DIR_REGEX } from '../types.js'
import { MEMON_RELEASE } from '../version.js'
import { yamlEngine } from '../yaml-engine.js'
import {
  EXPERIMENT_DESCRIPTION_FILE,
  missingExperimentDescription,
  parseExperimentDescription,
} from './description.js'
import { type ResultsDiagnostic, resultsDiagnostic } from './diagnostics.js'
import { RESULT_FILE_NAME } from './result-file.js'
import {
  generateResultsSummary,
  RESULTS_SUMMARY_VERSION,
  type ResultsSummary,
  type ResultsSummaryError,
  resultsSummaryDigest,
  type SummaryMemberInput,
  type SummaryRunRecord,
} from './summary.js'

export const RESULTS_CACHE_FAILED = 'RESULTS_CACHE_FAILED'
export const EXPERIMENTS_RELDIR = 'docs/experiments'
export const LEGACY_RESULTS_FILE = 'results.yaml'

export interface ResultsSummaryInputSet {
  experimentId: string
  /** Project-relative Experiment folder. */
  experimentDir: string
  /** README `runs` verbatim. */
  readmeRuns: string[]
  /** Declared members in path form (legacy bare IDs are not inputs). */
  members: string[]
  /** Project-relative description file. */
  descriptionKey: string
  /** A leftover `results.yaml` is present. */
  legacyResultsYaml: boolean
  /** Every input, description first, then `README.md` and `result.csv` per member. */
  keys: string[]
}

async function statOrNull(fs: IndexFs, path: string) {
  try {
    return await fs.stat(path)
  } catch (error) {
    const code = errnoCode(error)
    if (code === 'ENOENT' || code === 'ENOTDIR') return null
    throw error
  }
}

async function readOrNull(fs: IndexFs, path: string): Promise<string | null> {
  try {
    return (await fs.readFile(path, 'utf8')) as string
  } catch (error) {
    const code = errnoCode(error)
    if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'EISDIR') return null
    throw error
  }
}

const absolute = (root: string, key: string) => join(root, ...key.split('/'))

/**
 * The input set of an Experiment's summary from its README, or null when the
 * Experiment folder has no README (a legacy single-file Experiment has none).
 */
export async function readResultsSummaryInputSet(
  projectRoot: string,
  experimentId: string,
  options: { fs?: IndexFs } = {},
): Promise<ResultsSummaryInputSet | null> {
  if (!EXPERIMENT_DIR_REGEX.test(experimentId)) return null
  const fs = options.fs ?? defaultIndexFs
  const experimentDir = `${EXPERIMENTS_RELDIR}/${experimentId}`
  const readme = await readOrNull(fs, absolute(projectRoot, `${experimentDir}/README.md`))
  if (readme === null) return null
  const readmeRuns = [...parseExperimentReadme(readme, experimentId).frontMatter.runs]
  const members = [...new Set(readmeRuns.filter((run) => isRunPath(run)))]
  const descriptionKey = `${experimentDir}/${EXPERIMENT_DESCRIPTION_FILE}`
  const legacy = await statOrNull(
    fs,
    absolute(projectRoot, `${experimentDir}/${LEGACY_RESULTS_FILE}`),
  )
  return {
    experimentId,
    experimentDir,
    readmeRuns,
    members,
    descriptionKey,
    legacyResultsYaml: legacy?.isFile() === true,
    keys: [
      descriptionKey,
      ...members.flatMap((run) => [`${run}/README.md`, `${run}/${RESULT_FILE_NAME}`]),
    ],
  }
}

export type KnownFingerprint = (key: string) => PersistedFingerprint | null | undefined

/** Fingerprint every input key (a known fingerprint skips the stat). */
export async function takeResultsInputFingerprints(
  projectRoot: string,
  keys: readonly string[],
  options: { fs?: IndexFs; known?: KnownFingerprint } = {},
): Promise<Record<string, PersistedFingerprint | null>> {
  const fs = options.fs ?? defaultIndexFs
  const out: Record<string, PersistedFingerprint | null> = {}
  await Promise.all(
    keys.map(async (key) => {
      const known = options.known?.(key)
      out[key] = known !== undefined ? known : await takeFingerprint(absolute(projectRoot, key), fs)
    }),
  )
  const ordered: Record<string, PersistedFingerprint | null> = {}
  for (const key of keys) ordered[key] = out[key] ?? null
  return ordered
}

/** The path of an Experiment's stored summary. */
export function resultsSummaryPath(projectRoot: string, experimentId: string): string {
  return `${resolveIndexPaths(projectRoot).results}/${experimentId}.json`
}

/** The stored summary when it parses and its digest matches its content; otherwise null. */
export async function readStoredResultsSummary(
  projectRoot: string,
  experimentId: string,
  options: { fs?: IndexFs } = {},
): Promise<ResultsSummary | null> {
  const fs = options.fs ?? defaultIndexFs
  const raw = await readOrNull(fs, resultsSummaryPath(projectRoot, experimentId)).catch(() => null)
  if (raw === null) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    return null
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return null
  const summary = parsed as ResultsSummary
  if (summary.summary_version !== RESULTS_SUMMARY_VERSION) return null
  if (summary.experiment !== experimentId) return null
  if (typeof summary.digest !== 'string' || resultsSummaryDigest(summary) !== summary.digest)
    return null
  return summary
}

/** Whether a stored summary may be served for `inputs` (equal set, equal fingerprints, same release). */
export function isResultsSummaryFresh(
  summary: ResultsSummary,
  inputs: Readonly<Record<string, PersistedFingerprint | null>>,
  release: string = MEMON_RELEASE,
): boolean {
  if (summary.generator?.release !== release) return false
  const recorded = Object.keys(summary.inputs ?? {})
  const current = Object.keys(inputs)
  if (recorded.length !== current.length) return false
  return current.every(
    (key) =>
      Object.hasOwn(summary.inputs, key) && sameFingerprint(summary.inputs[key], inputs[key]),
  )
}

/** Replace the stored summary atomically (hidden temp file + rename). Throws on failure. */
export async function writeResultsSummary(
  projectRoot: string,
  summary: ResultsSummary,
  options: { fs?: IndexFs } = {},
): Promise<void> {
  const fs = options.fs ?? defaultIndexFs
  const paths = resolveIndexPaths(projectRoot)
  await ensureIndexDirectory(paths, { fs })
  await fs.mkdir(paths.results, { recursive: true })
  const temporary = `${paths.results}/.tmp-${summary.experiment}-${randomHex8()}`
  try {
    await fs.writeFile(temporary, `${JSON.stringify(summary)}\n`, { encoding: 'utf8', flag: 'wx' })
    await fs.rename(temporary, resultsSummaryPath(projectRoot, summary.experiment))
  } catch (error) {
    await fs.rm(temporary, { force: true }).catch(() => undefined)
    throw error
  }
}

/** Delete an Experiment's stored summary (absent is fine). */
export async function deleteResultsSummary(
  projectRoot: string,
  experimentId: string,
  options: { fs?: IndexFs } = {},
): Promise<void> {
  const fs = options.fs ?? defaultIndexFs
  await fs.rm(resultsSummaryPath(projectRoot, experimentId), { force: true })
}

/** The Run README facts a summary reads (`stop_reason` is read when present). */
export function summaryRunRecord(readme: string): SummaryRunRecord {
  const parsed = parseReadme(readme)
  let stopReason: string | null = null
  if (readme.includes('stop_reason')) {
    const split = splitFrontmatter(readme)
    if (split.status === 'ok') {
      try {
        const value = (yamlEngine.parse(split.raw) as Record<string, unknown> | null)?.stop_reason
        if (typeof value === 'string' && value.length > 0) stopReason = value
      } catch {}
    }
  }
  return {
    status: parsed.frontMatter.status,
    deprecated: parsed.frontMatter.deprecated,
    stop_reason: stopReason,
  }
}

export interface GenerateStoredSummaryOptions {
  fs?: IndexFs
  now?: () => Date
  role?: string
  release?: string
}

/** Read the inputs of `set` and generate its summary (no cache involved). */
export async function generateResultsSummaryFromDisk(
  projectRoot: string,
  set: ResultsSummaryInputSet,
  inputs: Record<string, PersistedFingerprint | null>,
  options: GenerateStoredSummaryOptions = {},
): Promise<ResultsSummary> {
  const fs = options.fs ?? defaultIndexFs
  const descriptionRaw = await readOrNull(fs, absolute(projectRoot, set.descriptionKey))
  const description =
    descriptionRaw === null
      ? missingExperimentDescription(set.descriptionKey)
      : parseExperimentDescription(descriptionRaw, set.descriptionKey)
  const members: SummaryMemberInput[] = await Promise.all(
    set.members.map(async (run) => {
      const [readme, result] = await Promise.all([
        inputs[`${run}/README.md`] === null
          ? null
          : readOrNull(fs, absolute(projectRoot, `${run}/README.md`)),
        inputs[`${run}/${RESULT_FILE_NAME}`] === null
          ? null
          : readOrNull(fs, absolute(projectRoot, `${run}/${RESULT_FILE_NAME}`)),
      ])
      return { path: run, record: readme === null ? null : summaryRunRecord(readme), result }
    }),
  )
  let newest = Number.NEGATIVE_INFINITY
  for (const fingerprint of Object.values(inputs))
    if (fingerprint && fingerprint.mtime_ms > newest) newest = fingerprint.mtime_ms
  return generateResultsSummary({
    experimentId: set.experimentId,
    experimentDir: set.experimentDir,
    description,
    legacyResultsYaml: set.legacyResultsYaml,
    members,
    inputs,
    newestInputMtime: Number.isFinite(newest) ? formatIsoLocal(new Date(newest)) : null,
    generatedAt: formatIsoLocal((options.now ?? (() => new Date()))()),
    generator: { release: options.release ?? MEMON_RELEASE, role: options.role ?? 'cli' },
  })
}

export interface LoadResultsSummaryOptions extends GenerateStoredSummaryOptions {
  /** Regenerate even when the stored summary is fresh. */
  refresh?: boolean
  /** Store a regenerated summary, best effort (default true). */
  write?: boolean
  /** Fingerprints already validated by the caller (central's index windows). */
  known?: KnownFingerprint
}

export interface LoadedResultsSummary {
  summary: ResultsSummary
  /** `hit`: the stored summary was fresh; `regenerated`: computed from the inputs. */
  cache: 'hit' | 'regenerated'
  /** A regenerated summary was stored. */
  written: boolean
  /** `RESULTS_CACHE_FAILED` when storing failed (the result is still correct). */
  warnings: ResultsDiagnostic[]
}

/**
 * The current summary of `experimentId`: the stored one when fresh,
 * otherwise regenerated (and stored best effort). Null when the Experiment
 * folder or its README does not exist. A failed summary is a normal result
 * (`outcome: 'failed'`), never an exception.
 */
export async function loadResultsSummary(
  projectRoot: string,
  experimentId: string,
  options: LoadResultsSummaryOptions = {},
): Promise<LoadedResultsSummary | null> {
  const fs = options.fs ?? defaultIndexFs
  const set = await readResultsSummaryInputSet(projectRoot, experimentId, { fs })
  if (!set) return null
  const inputs = await takeResultsInputFingerprints(projectRoot, set.keys, {
    fs,
    ...(options.known ? { known: options.known } : {}),
  })
  if (!options.refresh) {
    const stored = await readStoredResultsSummary(projectRoot, experimentId, { fs })
    if (stored && isResultsSummaryFresh(stored, inputs, options.release ?? MEMON_RELEASE))
      return { summary: stored, cache: 'hit', written: false, warnings: [] }
  }
  const summary = await generateResultsSummaryFromDisk(projectRoot, set, inputs, options)
  if (options.write === false)
    return { summary, cache: 'regenerated', written: false, warnings: [] }
  try {
    await writeResultsSummary(projectRoot, summary, { fs })
    return { summary, cache: 'regenerated', written: true, warnings: [] }
  } catch (error) {
    return {
      summary,
      cache: 'regenerated',
      written: false,
      warnings: [
        resultsDiagnostic(
          RESULTS_CACHE_FAILED,
          'warning',
          `.memon/index/results/${experimentId}.json`,
          `the regenerated Results summary was not stored: ${(error as Error)?.message ?? String(error)}`,
        ),
      ],
    }
  }
}

export interface RebuiltResultsSummary {
  id: string
  status: 'regenerated' | 'unchanged' | 'failed'
  error?: ResultsSummaryError
  warnings: ResultsDiagnostic[]
}

function comparable(summary: ResultsSummary): string {
  const { digest: _digest, generated_at: _at, ...rest } = summary
  return JSON.stringify(rest)
}

/**
 * Regenerate the summaries of `experiments` (default: every Experiment
 * folder) and replace each one atomically. One failure never stops the
 * others; `unchanged` means the stored summary already had this content.
 */
export async function rebuildResultsSummaries(
  projectRoot: string,
  options: GenerateStoredSummaryOptions & { experiments?: readonly string[] } = {},
): Promise<RebuiltResultsSummary[]> {
  const fs = options.fs ?? defaultIndexFs
  const ids =
    options.experiments ??
    (await listExperimentIds(projectRoot)).filter((id) => EXPERIMENT_DIR_REGEX.test(id))
  const out: RebuiltResultsSummary[] = []
  for (const id of ids) {
    const set = await readResultsSummaryInputSet(projectRoot, id, { fs })
    if (!set) {
      out.push({
        id,
        status: 'failed',
        error: {
          code: 'RESULTS_NOT_FOUND',
          message: `${EXPERIMENTS_RELDIR}/${id}/README.md does not exist`,
          files: [{ path: `${EXPERIMENTS_RELDIR}/${id}/README.md` }],
        },
        warnings: [],
      })
      continue
    }
    const inputs = await takeResultsInputFingerprints(projectRoot, set.keys, { fs })
    const summary = await generateResultsSummaryFromDisk(projectRoot, set, inputs, options)
    const stored = await readStoredResultsSummary(projectRoot, id, { fs })
    const warnings: ResultsDiagnostic[] = []
    const unchanged = stored !== null && comparable(stored) === comparable(summary)
    if (!unchanged) {
      try {
        await writeResultsSummary(projectRoot, summary, { fs })
      } catch (error) {
        warnings.push(
          resultsDiagnostic(
            RESULTS_CACHE_FAILED,
            'warning',
            `.memon/index/results/${id}.json`,
            `the Results summary was not stored: ${(error as Error)?.message ?? String(error)}`,
          ),
        )
      }
    }
    out.push({
      id,
      status: summary.outcome === 'failed' ? 'failed' : unchanged ? 'unchanged' : 'regenerated',
      ...(summary.error ? { error: summary.error } : {}),
      warnings,
    })
  }
  return out
}

/**
 * Delete stored summaries that are known to be stale (their inputs changed);
 * returns the deleted Experiment ids. Used by an index rebuild.
 */
export async function pruneStaleResultsSummaries(
  projectRoot: string,
  options: { fs?: IndexFs; release?: string } = {},
): Promise<string[]> {
  const fs = options.fs ?? defaultIndexFs
  let names: string[]
  try {
    names = (await fs.readdir(resolveIndexPaths(projectRoot).results)) as string[]
  } catch {
    return []
  }
  const deleted: string[] = []
  for (const name of names.sort()) {
    if (name.startsWith('.') || !name.endsWith('.json')) continue
    const id = name.slice(0, -'.json'.length)
    const stored = await readStoredResultsSummary(projectRoot, id, { fs })
    const set = await readResultsSummaryInputSet(projectRoot, id, { fs })
    const fresh =
      stored !== null &&
      set !== null &&
      isResultsSummaryFresh(
        stored,
        await takeResultsInputFingerprints(projectRoot, set.keys, { fs }),
        options.release ?? MEMON_RELEASE,
      )
    if (fresh) continue
    await deleteResultsSummary(projectRoot, id, { fs })
    deleted.push(id)
  }
  return deleted
}
